<!-- @FIGURE_UI_BEGIN -->
<label>Initial speed v₀ (panel a, θ=45°): <output id="launchSpeedVal">40</output> m/s<input id="launchSpeedInput" type="range" min="20" max="60" step="1" value="40" oninput="document.getElementById('launchSpeedVal').value=this.value;update_launchSpeed(+this.value)"></label>
<label>Launch angle θ (panel b, v₀=50 m/s): <output id="launchAngleVal">45</output>°<input id="launchAngleInput" type="range" min="5" max="85" step="1" value="45" oninput="document.getElementById('launchAngleVal').value=this.value;update_launchAngle(+this.value)"></label>
<div style="display:flex;align-items:center;gap:4px;margin-top:4px"><button onclick="prevStep()">◀</button><span id="stepLabel" style="font-size:10px">Step 0/3</span><button onclick="nextStep()">▶</button></div>
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px">Default view: v₀=40 m/s at 45° in panel (a); θ=45° at 50 m/s in panel (b).</p>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var g = 9.8;
var ORANGE = '#e8763a';
var PURPLE = '#9c4dcc';
var TEAL = '#26a69a';
var currentSpeed = 40;
var currentAngle = 45;
var currentStep = 0;

var demoSteps = [
  { title: 'Default view', narration: 'Default view: v₀=40 m/s at 45° in panel (a); θ=45° at 50 m/s in panel (b).', state: { launchSpeed: 40, launchAngle: 45 } },
  { title: 'Speed controls range quadratically', narration: 'In panel (a) the angle is locked at 45°. The speed is now 50 m/s and the range bar shows ~255 m — far more than proportional to the 30 m/s case (~92 m), because R grows with v₀².', state: { launchSpeed: 50, launchAngle: 45 } },
  { title: '45° gives maximum range', narration: 'In panel (b) the speed is locked at 50 m/s. At 45° the range bar reaches its longest value (255 m); moving to either side shortens the range symmetrically.', state: { launchSpeed: 40, launchAngle: 45 } },
  { title: 'Complementary angles share range, not height', narration: 'Set the angle to 15° and notice the faint 75° complement arc lands at exactly the same x (R ≈ 128 m) yet soars to a much higher apex — same horizontal reach, traded for vertical height.', state: { launchSpeed: 40, launchAngle: 15 } }
];

function getRange(v0, thetaDeg) {
  var th = thetaDeg * Math.PI / 180;
  return v0 * v0 * Math.sin(2 * th) / g;
}

function getApex(v0, thetaDeg) {
  var th = thetaDeg * Math.PI / 180;
  return { x: getRange(v0, thetaDeg) / 2, y: v0 * v0 * Math.sin(th) * Math.sin(th) / (2 * g) };
}

function getTrajectory(v0, thetaDeg, n) {
  n = n || 100;
  var th = thetaDeg * Math.PI / 180;
  var T = 2 * v0 * Math.sin(th) / g;
  var pts = [];
  for (var i = 0; i <= n; i++) {
    var t = T * i / n;
    var x = v0 * Math.cos(th) * t;
    var y = v0 * Math.sin(th) * t - 0.5 * g * t * t;
    pts.push({ x: x, y: Math.max(0, y) });
  }
  return pts;
}

function lerpColor(c1, c2, t) {
  return [
    Math.round(c1[0] + (c2[0] - c1[0]) * t),
    Math.round(c1[1] + (c2[1] - c1[1]) * t),
    Math.round(c1[2] + (c2[2] - c1[2]) * t)
  ];
}

function speedColor(v0) {
  var t = (v0 - 20) / 40;
  t = Math.max(0, Math.min(1, t));
  var c;
  if (t <= 0.5) { c = lerpColor([232,118,58],[156,77,204], t*2); }
  else { c = lerpColor([156,77,204],[38,166,154], (t-0.5)*2); }
  return 'rgb(' + c[0] + ',' + c[1] + ',' + c[2] + ')';
}

function angleColor(theta) {
  var t = (theta - 5) / 80;
  t = Math.max(0, Math.min(1, t));
  var c;
  if (t <= 0.5) { c = lerpColor([232,118,58],[156,77,204], t*2); }
  else { c = lerpColor([156,77,204],[38,166,154], (t-0.5)*2); }
  return 'rgb(' + c[0] + ',' + c[1] + ',' + c[2] + ')';
}

function drawArrowHead(ctx, x, y, angle, size, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - size * Math.cos(angle - 0.35), y - size * Math.sin(angle - 0.35));
  ctx.lineTo(x - size * Math.cos(angle + 0.35), y - size * Math.sin(angle + 0.35));
  ctx.closePath();
  ctx.fill();
}

function drawArrow(ctx, x1, y1, x2, y2, color, lw, hs) {
  hs = hs || 8;
  var angle = Math.atan2(y2 - y1, x2 - x1);
  ctx.strokeStyle = color;
  ctx.lineWidth = lw || 2;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  drawArrowHead(ctx, x2, y2, angle, hs, color);
}

function drawDoubleArrow(ctx, x1, y, x2, color, lw, hs) {
  hs = hs || 5;
  ctx.strokeStyle = color;
  ctx.lineWidth = lw || 1.2;
  ctx.beginPath();
  ctx.moveTo(x1, y);
  ctx.lineTo(x2, y);
  ctx.stroke();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x1, y);
  ctx.lineTo(x1 + hs, y - hs * 0.5);
  ctx.lineTo(x1 + hs, y + hs * 0.5);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(x2, y);
  ctx.lineTo(x2 - hs, y - hs * 0.5);
  ctx.lineTo(x2 - hs, y + hs * 0.5);
  ctx.closePath();
  ctx.fill();
}

function drawTrajectory(ctx, pts, xFn, yFn, color, lw, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha || 1;
  ctx.strokeStyle = color;
  ctx.lineWidth = lw || 2;
  ctx.beginPath();
  for (var i = 0; i < pts.length; i++) {
    var sx = xFn(pts[i].x);
    var sy = yFn(pts[i].y);
    if (i === 0) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  }
  ctx.stroke();
  ctx.restore();
}

var projectilePlugin = {
  id: 'projectileFigure',
  afterDraw: function(chart) {
    var ctx = chart.ctx;
    var W = chart.canvas.width;
    var H = chart.canvas.height;
    var dpr = window.devicePixelRatio || 1;
    W = W / dpr;
    H = H / dpr;
    ctx.save();
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);

    var mL = 30, mR = 20, mT = 15, mB = 5;
    var gapBetween = 25;
    var rangeBarSpace = 55;
    var availH = H - mT - mB - gapBetween - rangeBarSpace * 2;
    var panelH = Math.max(50, availH / 2);

    var pA = { x: mL, y: mT, w: W - mL - mR, h: panelH, groundY: mT + panelH, rTop: mT + panelH + 4, rBot: mT + panelH + rangeBarSpace };
    var pB = { x: mL, y: pA.rBot + gapBetween, w: W - mL - mR, h: panelH, groundY: pA.rBot + gapBetween + panelH, rTop: pA.rBot + gapBetween + panelH + 4, rBot: pA.rBot + gapBetween + panelH + rangeBarSpace };

    var xMax = 280;
    function xsA(xw) { return pA.x + (xw / xMax) * pA.w; }
    function xsB(xw) { return pB.x + (xw / xMax) * pB.w; }
    var yMaxA = 70;
    function ysA(yw) { return pA.groundY - (yw / yMaxA) * pA.h; }
    var yMaxB = 130;
    function ysB(yw) { return pB.groundY - (yw / yMaxB) * pB.h; }

    // ===== PANEL (a) =====
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(pA.x, pA.groundY);
    ctx.lineTo(pA.x + pA.w, pA.groundY);
    ctx.stroke();

    var ghostsA = [
      { v0: 30, color: ORANGE, R: getRange(30, 45), label: '30 m/s' },
      { v0: 40, color: PURPLE, R: getRange(40, 45), label: '40 m/s' },
      { v0: 50, color: TEAL, R: getRange(50, 45), label: '50 m/s' }
    ];

    for (var gi = 0; gi < ghostsA.length; gi++) {
      var gh = ghostsA[gi];
      var pts = getTrajectory(gh.v0, 45, 80);
      drawTrajectory(ctx, pts, xsA, ysA, gh.color, 1.5, 0.35);
      var ap = getApex(gh.v0, 45);
      ctx.save();
      ctx.setLineDash([4, 3]);
      ctx.strokeStyle = '#888';
      ctx.lineWidth = 0.8;
      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      ctx.moveTo(xsA(ap.x), ysA(ap.y));
      ctx.lineTo(xsA(ap.x), pA.groundY);
      ctx.stroke();
      ctx.restore();
    }

    // Live arc panel (a)
    var lcA = speedColor(currentSpeed);
    var livePtsA = getTrajectory(currentSpeed, 45, 120);
    drawTrajectory(ctx, livePtsA, xsA, ysA, lcA, 2.5, 1);
    var liveApexA = getApex(currentSpeed, 45);
    ctx.save();
    ctx.setLineDash([4, 3]);
    ctx.strokeStyle = '#555';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(xsA(liveApexA.x), ysA(liveApexA.y));
    ctx.lineTo(xsA(liveApexA.x), pA.groundY);
    ctx.stroke();
    ctx.restore();

    // Launch arrow panel (a)
    var aLen = Math.min(55, pA.h * 0.4);
    var th45 = 45 * Math.PI / 180;
    var ox = xsA(0), oy = ysA(0);
    drawArrow(ctx, ox, oy, ox + aLen * Math.cos(th45), oy - aLen * Math.sin(th45), lcA, 2.5, 9);
    ctx.font = 'italic 11px serif';
    ctx.fillStyle = lcA;
    ctx.textAlign = 'left';
    ctx.fillText(currentSpeed + ' m/s', ox + aLen * Math.cos(th45) + 4, oy - aLen * Math.sin(th45) - 4);

    // 45° arc
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(ox, oy, 22, -th45, 0);
    ctx.stroke();
    ctx.font = '10px sans-serif';
    ctx.fillStyle = '#333';
    ctx.fillText('45°', ox + 25, oy - 6);

    // Range bars panel (a)
    var barSpacing = 16;
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    for (var ri = 0; ri < ghostsA.length; ri++) {
      var by = pA.rTop + 10 + ri * barSpacing;
      var rVal = ghostsA[ri].R;
      drawDoubleArrow(ctx, xsA(0), by, xsA(rVal), '#555', 1, 4);
      ctx.fillStyle = '#444';
      var rLabel = rVal < 100 ? 'R = ' + rVal.toFixed(1) + ' m' : 'R = ' + Math.round(rVal) + ' m';
      ctx.fillText(rLabel, xsA(rVal / 2), by - 3);
    }
    // Live range bar
    var liveR_A = getRange(currentSpeed, 45);
    var liveBarY = pA.rTop + 10 + 3 * barSpacing;
    drawDoubleArrow(ctx, xsA(0), liveBarY, xsA(liveR_A), lcA, 2, 5);
    ctx.fillStyle = lcA;
    ctx.font = 'bold 10px sans-serif';
    ctx.fillText('R = ' + liveR_A.toFixed(1) + ' m', xsA(liveR_A / 2), liveBarY - 3);

    // Panel (a) label
    ctx.font = '12px sans-serif';
    ctx.fillStyle = '#333';
    ctx.textAlign = 'center';
    ctx.fillText('(a)', pA.x + pA.w / 2, pA.rBot + 14);

    // Orientation key
    var kx = W - mR - 55, ky = mT + 8;
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(kx, ky + 28); ctx.lineTo(kx + 35, ky + 28); ctx.stroke();
    drawArrowHead(ctx, kx + 35, ky + 28, 0, 6, '#333');
    ctx.beginPath(); ctx.moveTo(kx, ky + 28); ctx.lineTo(kx, ky + 2); ctx.stroke();
    drawArrowHead(ctx, kx, ky + 2, -Math.PI / 2, 6, '#333');
    ctx.font = 'italic 11px serif';
    ctx.fillStyle = '#333';
    ctx.textAlign = 'left';
    ctx.fillText('x', kx + 38, ky + 32);
    ctx.fillText('y', kx - 3, ky - 2);

    // ===== PANEL (b) =====
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(pB.x, pB.groundY);
    ctx.lineTo(pB.x + pB.w, pB.groundY);
    ctx.stroke();

    var ghostsB = [
      { th: 15, color: ORANGE, R: getRange(50, 15) },
      { th: 45, color: PURPLE, R: getRange(50, 45) },
      { th: 75, color: TEAL, R: getRange(50, 75) }
    ];

    for (var gj = 0; gj < ghostsB.length; gj++) {
      var gb = ghostsB[gj];
      var ptsB = getTrajectory(50, gb.th, 80);
      drawTrajectory(ctx, ptsB, xsB, ysB, gb.color, 1.5, 0.35);
      var apB = getApex(50, gb.th);
      ctx.save();
      ctx.setLineDash([4, 3]);
      ctx.strokeStyle = '#888';
      ctx.lineWidth = 0.8;
      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      ctx.moveTo(xsB(apB.x), ysB(apB.y));
      ctx.lineTo(xsB(apB.x), pB.groundY);
      ctx.stroke();
      ctx.restore();
    }

    // Complement arc (90 - currentAngle)
    var compAngle = 90 - currentAngle;
    if (Math.abs(compAngle - currentAngle) > 1) {
      var compPts = getTrajectory(50, compAngle, 80);
      ctx.save();
      ctx.setLineDash([5, 4]);
      drawTrajectory(ctx, compPts, xsB, ysB, angleColor(compAngle), 1.2, 0.4);
      ctx.restore();
    }

    // Live arc panel (b)
    var lcB = angleColor(currentAngle);
    var livePtsB = getTrajectory(50, currentAngle, 120);
    drawTrajectory(ctx, livePtsB, xsB, ysB, lcB, 2.5, 1);
    var liveApexB = getApex(50, currentAngle);
    ctx.save();
    ctx.setLineDash([4, 3]);
    ctx.strokeStyle = '#555';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(xsB(liveApexB.x), ysB(liveApexB.y));
    ctx.lineTo(xsB(liveApexB.x), pB.groundY);
    ctx.stroke();
    ctx.restore();

    // Launch arrow panel (b)
    var thLive = currentAngle * Math.PI / 180;
    var ox2 = xsB(0), oy2 = ysB(0);
    var aLen2 = Math.min(55, pB.h * 0.35);
    drawArrow(ctx, ox2, oy2, ox2 + aLen2 * Math.cos(thLive), oy2 - aLen2 * Math.sin(thLive), lcB, 2.5, 9);
    ctx.font = 'italic 11px serif';
    ctx.fillStyle = lcB;
    ctx.textAlign = 'left';
    ctx.fillText('v₀ = 50 m/s', ox2 + 5, oy2 - aLen2 - 8);

    // Angle arcs panel (b)
    var arcRadii = [18, 26, 34];
    var refAngles = [15, 45, 75];
    for (var ai = 0; ai < refAngles.length; ai++) {
      var ar = refAngles[ai] * Math.PI / 180;
      ctx.strokeStyle = '#555';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.arc(ox2, oy2, arcRadii[ai], -ar, 0);
      ctx.stroke();
    }
    // Live angle arc
    ctx.strokeStyle = lcB;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(ox2, oy2, 42, -thLive, 0);
    ctx.stroke();
