function getRange(v0, thetaDeg) {
  var th = thetaDeg * Math.PI / 180;
  return v0 * v0 * Math.sin(2 * th) / g;
}

function getApex(v0, thetaDeg) {
  var th = thetaDeg * Math.PI / 180;
  return { x: getRange(v0, thetaDeg) / 2, y: v0 * v0 * Math.sin(th) * Math.sin(th) / (2 * g) };
}

function getTrajectory(v0, thetaDeg, n) {
  n = n || 100;
  var th = thetaDeg * Math.PI / 180;
  var T = 2 * v0 * Math.sin(th) / g;
  var pts = [];
  for (var i = 0; i <= n; i++) {
    var t = T * i / n;
    var x = v0 * Math.cos(th) * t;
    var y = v0 * Math.sin(th) * t - 0.5 * g * t * t;
    pts.push({ x: x, y: Math.max(0, y) });
  }
  return pts;
}

function lerpColor(c1, c2, t) {
  return [
    Math.round(c1[0] + (c2[0] - c1[0]) * t),
    Math.round(c1[1] + (c2[1] - c1[1]) * t),
    Math.round(c1[2] + (c2[2] - c1[2]) * t)
  ];
}

function speedColor(v0) {
  var t = (v0 - 20) / 40;
  t = Math.max(0, Math.min(1, t));
  var c;
  if (t <= 0.5) { c = lerpColor([232,118,58],[156,77,204], t*2); }
  else { c = lerpColor([156,77,204],[38,166,154], (t-0.5)*2); }
  return 'rgb(' + c[0] + ',' + c[1] + ',' + c[2] + ')';
}

function angleColor(theta) {
  var t = (theta - 5) / 80;
  t = Math.max(0, Math.min(1, t));
  var c;
  if (t <= 0.5) { c = lerpColor([232,118,58],[156,77,204], t*2); }
  else { c = lerpColor([156,77,204],[38,166,154], (t-0.5)*2); }
  return 'rgb(' + c[0] + ',' + c[1] + ',' + c[2] + ')';
}

function drawArrowHead(ctx, x, y, angle, size, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - size * Math.cos(angle - 0.35), y - size * Math.sin(angle - 0.35));
  ctx.lineTo(x - size * Math.cos(angle + 0.35), y - size * Math.sin(angle + 0.35));
  ctx.closePath();
  ctx.fill();
}

function drawArrow(ctx, x1, y1, x2, y2, color, lw, hs) {
  hs = hs || 8;
  var angle = Math.atan2(y2 - y1, x2 - x1);
  ctx.strokeStyle = color;
  ctx.lineWidth = lw || 2;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  drawArrowHead(ctx, x2, y2, angle, hs, color);
}

function drawDoubleArrow(ctx, x1, y, x2, color, lw, hs) {
  hs = hs || 5;
  ctx.strokeStyle = color;
  ctx.lineWidth = lw || 1.2;
  ctx.beginPath();
  ctx.moveTo(x1, y);
  ctx.lineTo(x2, y);
  ctx.stroke();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x1, y);
  ctx.lineTo(x1 + hs, y - hs * 0.5);
  ctx.lineTo(x1 + hs, y + hs * 0.5);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(x2, y);
  ctx.lineTo(x2 - hs, y - hs * 0.5);
  ctx.lineTo(x2 - hs, y + hs * 0.5);
  ctx.closePath();
  ctx.fill();
}

function drawTrajectory(ctx, pts, xFn, yFn, color, lw, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha || 1;
  ctx.strokeStyle = color;
  ctx.lineWidth = lw || 2;
  ctx.beginPath();
  for (var i = 0; i < pts.length; i++) {
    var sx = xFn(pts[i].x);
    var sy = yFn(pts[i].y);
    if (i === 0) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  }
  ctx.stroke();
  ctx.restore();
}

