<!-- @FIGURE_UI_BEGIN -->
<label>Highlight speed (panel a, θ=45°): <output id="highlightSpeedVal">40</output> m/s<input id="highlightSpeedInput" type="range" min="30" max="50" step="10" value="40" oninput="document.getElementById('highlightSpeedVal').value=this.value;update_highlightSpeed(+this.value)"></label>
