  { title: 'All trajectories equally visible', narration: 'Both panels show all three trajectories at full opacity in their source colors (orange, purple, teal). Each has its own launch arrow, apex guide, and range bar — the complete picture of how speed and angle affect projectile motion.', state: { highlightSpeed: 40, highlightAngle: 45 } },
  { title: 'Speed controls range quadratically', narration: 'In panel (a), the slider highlights the teal (50 m/s) trajectory with a thicker stroke. Compare its range bar (255 m) to the orange (30 m/s) bar (91.8 m) — the range nearly triples because R ∝ v₀².', state: { highlightSpeed: 50, highlightAngle: 45 } },
  { title: '45° gives maximum range', narration: 'In panel (b), the slider highlights the purple (45°) trajectory. Its range bar (255 m) is the longest — no other angle at this speed can match it.', state: { highlightSpeed: 40, highlightAngle: 45 } },
  { title: 'Complementary angles share range, not height', narration: 'Highlight the orange (15°) arc in panel (b). Notice the teal (75°) arc has an identical range (128 m) yet soars to a much higher apex — same horizontal reach, traded for vertical height.', state: { highlightSpeed: 40, highlightAngle: 15 } }
];

function getRange(v0, thetaDeg) {
  var th = thetaDeg * Math.PI / 180;
  return v0 * v0 * Math.sin(2 * th) / g;
}

function getApex(v0, thetaDeg) {
  var th = thetaDeg * Math.PI / 180;
  return { x: getRange(v0, thetaDeg) / 2, y: v0 * v0 * Math.sin(th) * Math.sin(th) / (2 * g) };
}

function getTrajectory(v0, thetaDeg, n) {
  n = n || 120;
  var th = thetaDeg * Math.PI / 180;
  var T = 2 * v0 * Math.sin(th) / g;
  var pts = [];
  for (var i = 0; i <= n; i++) {
    var t = T * i / n;
    var x = v0 * Math.cos(th) * t;
    var y = v0 * Math.sin(th) * t - 0.5 * g * t * t;
    pts.push({ x: x, y: Math.max(0, y) });
  }
  return pts;
}

function drawArrowHead(ctx, x, y, angle, size, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - size * Math.cos(angle - 0.35), y - size * Math.sin(angle - 0.35));
  ctx.lineTo(x - size * Math.cos(angle + 0.35), y - size * Math.sin(angle + 0.35));
  ctx.closePath();
  ctx.fill();
}

function drawArrow(ctx, x1, y1, x2, y2, color, lw, hs) {
  hs = hs || 7;
  var angle = Math.atan2(y2 - y1, x2 - x1);
  ctx.strokeStyle = color;
  ctx.lineWidth = lw || 2;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  drawArrowHead(ctx, x2, y2, angle, hs, color);
}

function drawRangeBar(ctx, x1, y, x2, text, highlighted) {
  var color = BLACK;
  var lw = highlighted ? 1.8 : 1.2;
  var hs = 5;
  var tickH = 6;

  // Horizontal line
  ctx.strokeStyle = color;
  ctx.lineWidth = lw;
  ctx.beginPath();
  ctx.moveTo(x1, y);
  ctx.lineTo(x2, y);
  ctx.stroke();

  // Left arrowhead (pointing left)
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x1, y);
  ctx.lineTo(x1 + hs, y - hs * 0.45);
  ctx.lineTo(x1 + hs, y + hs * 0.45);
  ctx.closePath();
  ctx.fill();

  // Right arrowhead (pointing right)
  ctx.beginPath();
  ctx.moveTo(x2, y);
  ctx.lineTo(x2 - hs, y - hs * 0.45);
  ctx.lineTo(x2 - hs, y + hs * 0.45);
  ctx.closePath();
  ctx.fill();

  // Vertical tick marks at ends
  ctx.beginPath();
  ctx.moveTo(x1, y - tickH);
  ctx.lineTo(x1, y + tickH);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x2, y - tickH);
  ctx.lineTo(x2, y + tickH);
  ctx.stroke();

  // Text label centered above
  ctx.font = (highlighted ? 'bold ' : '') + '12px sans-serif';
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.fillText(text, (x1 + x2) / 2, y - 5);
}

function drawTrajectory(ctx, pts, xFn, yFn, color, lw) {
  ctx.strokeStyle = color;
  ctx.lineWidth = lw || 2;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.beginPath();
  for (var i = 0; i < pts.length; i++) {
    var sx = xFn(pts[i].x);
    var sy = yFn(pts[i].y);
    if (i === 0) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  }
  ctx.stroke();
}

var projectilePlugin = {
  id: 'projectileFigure',
  afterDraw: function(chart) {
    var ctx = chart.ctx;
    var W = chart.canvas.width;
    var H = chart.canvas.height;
    var dpr = window.devicePixelRatio || 1;
    W = W / dpr;
    H = H / dpr;
    ctx.save();
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);

    var mL = 30, mR = 20, mT = 12, mB = 5;
    var gapBetween = 18;
    var rangeBarSpace = 56;
    var availH = H - mT - mB - gapBetween - rangeBarSpace * 2;
    var panelH = Math.max(50, availH / 2);

    var pA = { x: mL, y: mT, w: W - mL - mR, h: panelH, groundY: mT + panelH, rTop: mT + panelH + 8, rBot: mT + panelH + rangeBarSpace };
    var pB = { x: mL, y: pA.rBot + gapBetween, w: W - mL - mR, h: panelH, groundY: pA.rBot + gapBetween + panelH, rTop: pA.rBot + gapBetween + panelH + 8, rBot: pA.rBot + gapBetween + panelH + rangeBarSpace };

    var xMax = 280;
    function xsA(xw) { return pA.x + (xw / xMax) * pA.w; }
    function xsB(xw) { return pB.x + (xw / xMax) * pB.w; }
    var yMaxA = 70;
    function ysA(yw) { return pA.groundY - (yw / yMaxA) * pA.h; }
    var yMaxB = 130;
    function ysB(yw) { return pB.groundY - (yw / yMaxB) * pB.h; }

    // ===== PANEL (a) =====
    ctx.strokeStyle = BLACK;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(pA.x, pA.groundY);
    ctx.lineTo(pA.x + pA.w, pA.groundY);
    ctx.stroke();

    var speedsA = [
      { v0: 30, color: ORANGE, label: '30 m/s' },
      { v0: 40, color: PURPLE, label: '40 m/s' },
      { v0: 50, color: TEAL, label: '50 m/s' }
    ];

    for (var gi = 0; gi < speedsA.length; gi++) {
      var sa = speedsA[gi];
      var pts = getTrajectory(sa.v0, 45, 120);
      var isHighlighted = (sa.v0 === highlightSpeed);
      var lw = isHighlighted ? 3 : 2;
      drawTrajectory(ctx, pts, xsA, ysA, sa.color, lw);

      var ap = getApex(sa.v0, 45);
      ctx.save();
      ctx.setLineDash([4, 3]);
      ctx.strokeStyle = '#888';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(xsA(ap.x), ysA(ap.y));
      ctx.lineTo(xsA(ap.x), pA.groundY);
      ctx.stroke();
      ctx.restore();
    }

    // Launch arrows panel (a)
    var ox = xsA(0), oy = ysA(0);
    var maxArrowLen = Math.min(60, pA.h * 0.45);
    var th45 = 45 * Math.PI / 180;
    for (var ai = 0; ai < speedsA.length; ai++) {
      var arrowLen = maxArrowLen * (speedsA[ai].v0 / 50);
      var ax = ox + arrowLen * Math.cos(th45);
      var ay = oy - arrowLen * Math.sin(th45);
      drawArrow(ctx, ox, oy, ax, ay, speedsA[ai].color, 2, 7);
      // Label - 13px italic, offset further along arrow
      ctx.font = 'italic 13px serif';
      ctx.fillStyle = speedsA[ai].color;
      ctx.textAlign = 'right';
      var labelOffX = -6;
      var labelOffY = (ai === 0) ? 6 : (ai === 1) ? -2 : -8;
      ctx.fillText(speedsA[ai].label, ax + labelOffX, ay + labelOffY);
    }

    // 45° angle arc at origin
    ctx.strokeStyle = BLACK;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(ox, oy, 22, -th45, 0);
    ctx.stroke();
    ctx.font = '12px sans-serif';
    ctx.fillStyle = BLACK;
    ctx.textAlign = 'left';
    ctx.fillText('45°', ox + 25, oy - 6);

    // Range bars panel (a) - ALL BLACK
    var barSpacing = 17;
    var rangeTextsA = ['R = 91.8 m', 'R = 163 m', 'R = 255 m'];
    for (var ri = 0; ri < speedsA.length; ri++) {
      var rVal = getRange(speedsA[ri].v0, 45);
      var by = pA.rTop + 6 + ri * barSpacing;
      var isBarHL = (speedsA[ri].v0 === highlightSpeed);
      drawRangeBar(ctx, xsA(0), by, xsA(rVal), rangeTextsA[ri], isBarHL);
    }

    // Panel (a) label
    ctx.font = '13px sans-serif';
    ctx.fillStyle = BLACK;
    ctx.textAlign = 'center';
    ctx.fillText('(a)', pA.x + pA.w / 2, pA.rBot + 14);

    // Orientation key (upper right)
    var kx = W - mR - 50, ky = mT + 6;
    ctx.strokeStyle = BLACK;
    ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(kx, ky + 26); ctx.lineTo(kx + 32, ky + 26); ctx.stroke();
    drawArrowHead(ctx, kx + 32, ky + 26, 0, 5, BLACK);
    ctx.beginPath(); ctx.moveTo(kx, ky + 26); ctx.lineTo(kx, ky + 2); ctx.stroke();
    drawArrowHead(ctx, kx, ky + 2, -Math.PI / 2, 5, BLACK);
    ctx.font = 'italic 12px serif';
    ctx.fillStyle = BLACK;
    ctx.textAlign = 'left';
    ctx.fillText('x', kx + 35, ky + 30);
    ctx.fillText('y', kx - 4, ky);

    // ===== PANEL (b) =====
    ctx.strokeStyle = BLACK;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(pB.x, pB.groundY);
    ctx.lineTo(pB.x + pB.w, pB.groundY);
    ctx.stroke();

    var anglesB = [
      { th: 15, color: ORANGE, label: '15°' },
      { th: 45, color: PURPLE, label: '45°' },
      { th: 75, color: TEAL, label: '75°' }
    ];

    for (var gj = 0; gj < anglesB.length; gj++) {
      var gb = anglesB[gj];
      var ptsB = getTrajectory(50, gb.th, 120);
      var isHL_B = (gb.th === highlightAngle);
      var lwB = isHL_B ? 3 : 2;
      drawTrajectory(ctx, ptsB, xsB, ysB, gb.color, lwB);

      var apB = getApex(50, gb.th);
      ctx.save();
      ctx.setLineDash([4, 3]);
      ctx.strokeStyle = '#888';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(xsB(apB.x), ysB(apB.y));
      ctx.lineTo(xsB(apB.x), pB.groundY);
      ctx.stroke();
      ctx.restore();
    }

    // Launch arrows panel (b)
    var ox2 = xsB(0), oy2 = ysB(0);
    var arrowLenB = Math.min(55, pB.h * 0.38);
    for (var bi = 0; bi < anglesB.length; bi++) {
      var thB = anglesB[bi].th * Math.PI / 180;
      var bx = ox2 + arrowLenB * Math.cos(thB);
      var byy = oy2 - arrowLenB * Math.sin(thB);
      drawArrow(ctx, ox2, oy2, bx, byy, anglesB[bi].color, 2, 7);
    }

    // "v₀ = 50 m/s" label
    ctx.font = 'italic 13px serif';
    ctx.fillStyle = BLACK;
    ctx.textAlign = 'left';
    ctx.fillText('v₀ = 50 m/s', ox2 + 2, oy2 - arrowLenB - 12);

    // Angle arcs at origin
    var arcRadii = [18, 26, 34];
    for (var aci = 0; aci < anglesB.length; aci++) {
      var arRad = anglesB[aci].th * Math.PI / 180;
      ctx.strokeStyle = '#555';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.arc(ox2, oy2, arcRadii[aci], -arRad, 0);
      ctx.stroke();
    }

    // Angle labels - 12px
    ctx.font = '12px sans-serif';
    ctx.fillStyle = '#555';
    ctx.textAlign = 'left';
    ctx.fillText('15°', ox2 + 20, oy2 - 4);
    ctx.fillText('45°', ox2 + 28, oy2 - 18);
    ctx.fillText('75°', ox2 + 14, oy2 - 35);

    // Range bars panel (b) - TWO bars only (15° and 75° share R=128m)
    var r15 = getRange(50, 15);
    var r45 = getRange(50, 45);

    var isBar128HL = (highlightAngle === 15 || highlightAngle === 75);
    var isBar255HL = (highlightAngle === 45);

    drawRangeBar(ctx, xsB(0), pB.rTop + 6, xsB(r15), 'R = 128 m', isBar128HL);
    drawRangeBar(ctx, xsB(0), pB.rTop + 6 + barSpacing, xsB(r45), 'R = 255 m', isBar255HL);

    // Panel (b) label
    ctx.font = '13px sans-serif';
    ctx.fillStyle = BLACK;
    ctx.textAlign = 'center';
    ctx.fillText('(b)', pB.x + pB.w / 2, pB.rBot + 14);

    ctx.restore();
  }
};

var canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
document.getElementById('container').appendChild(canvas);

var chart = new Chart(canvas, {
  type: 'scatter',
  data: { datasets: [] },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: { x: { display: false }, y: { display: false } },
    animation: false
  },
  plugins: [projectilePlugin]
});

window.__markRendered();

function update_highlightSpeed(v) {
  highlightSpeed = v;
  chart.update('none');
}

function update_highlightAngle(v) {
  highlightAngle = v;
  chart.update('none');
}

function applyStep(idx) {
  currentStep = idx;
  var st = demoSteps[idx].state;
  highlightSpeed = st.highlightSpeed;
  highlightAngle = st.highlightAngle;
  document.getElementById('highlightSpeedInput').value = st.highlightSpeed;
  document.getElementById('highlightSpeedVal').value = st.highlightSpeed;
  document.getElementById('highlightAngleInput').value = st.highlightAngle;
  document.getElementById('highlightAngleVal').value = st.highlightAngle;
  document.getElementById('stepLabel').textContent = 'Step ' + idx + '/' + (demoSteps.length - 1);
  document.getElementById('demoNarration').textContent = demoSteps[idx].narration;
  chart.update('none');
}

function nextStep() {
  if (currentStep < demoSteps.length - 1) applyStep(currentStep + 1);
}

function prevStep() {
  if (currentStep > 0) applyStep(currentStep - 1);
}

applyStep(0);
